      }

      const dt = 0.01;
      const lagTau = knownParams ? knownParams.lag : 0.04;
      motorThrustLag += (lastAction.thrust - motorThrustLag) * (1 - Math.exp(-dt / lagTau));

      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const dirX = Math.cos(att.yaw) * bodyX + Math.sin(att.yaw) * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ;

      if (prevVel !== null && p.y > 0.085) {
        const ayMeas = (v.y - prevVel.y) / dt;
        const axMeas = (v.x - prevVel.x) / dt;
        const azMeas = (v.z - prevVel.z) / dt;

        const ayThrust = ayMeas + G + (DRAG / massEst) * prevVel.y;
        const sMeas = ayThrust / Math.max(0.5, dirY);
        if (!knownParams && motorThrustLag > 0.25 && lastAction.thrust < 0.92 && lastAction.thrust > 0.15) {
          const kCand = clamp(sMeas / motorThrustLag, 13.5, 26.8);
          kThrust += 0.08 * (kCand - kThrust);
          massEst = clamp((16 * 0.92) / kThrust, 0.6, 0.95);
        }

        const sBest = 0.65 * (kThrust * motorThrustLag) + 0.35 * clamp(sMeas, 2, 28);
        const axKnown = sBest * dirX - (DRAG / massEst) * prevVel.x;
        const azKnown = sBest * dirZ - (DRAG / massEst) * prevVel.z;
        const ayKnown = (kThrust * motorThrustLag) * dirY - G - (DRAG / massEst) * prevVel.y;

        const dRawX = clamp(axMeas - axKnown, -11, 11);
        const dRawZ = clamp(azMeas - azKnown, -11, 11);
        const dRawY = clamp(ayMeas - ayKnown, -5, 5);

        const alphaD = knownParams ? 0.25 : 0.30;
        dHatX += alphaD * (dRawX - dHatX);
        dHatZ += alphaD * (dRawZ - dHatZ);
        dHatY += 0.12 * (dRawY - dHatY);

        attIntRoll = clamp(attIntRoll + (lastDesiredRoll - att.roll) * dt, -0.22, 0.22);
        attIntPitch = clamp(attIntPitch + (lastDesiredPitch - att.pitch) * dt, -0.22, 0.22);
        yawInt = clamp(yawInt + att.yaw * dt, -0.6, 0.6);
      }

      prevVel = v;
      prevPos = p;
      stepIdx++;

      let windAccX = dHatX;
      let windAccZ = dHatZ;
      if (knownParams) {
        const lw = lookaheadWind(knownParams, obs.t);
        const exactWx = (DRAG / knownParams.mass) * lw.x;
        const exactWz = (DRAG / knownParams.mass) * lw.z;
        windAccX = 0.85 * exactWx + 0.15 * dHatX;
        windAccZ = 0.85 * exactWz + 0.15 * dHatZ;
      }

      let target = { x: p.x, y: 1.05, z: p.z };
      let vxRef = 0, vyRef = 0, vzRef = 0;
      let kpX = 6.5, kdX = 4.2;
      let kpY = 9.0, kdY = 5.0;
      let kpZ = 10.5, kdZ = 5.6;
      let maxTilt = 0.6;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settleCount = 0;
          posIntX = 0; posIntY = 0; posIntZ = 0;
        }

        const dxGate = gate.x - p.x;
        const dyGate = gate.y - p.y;
        const dzGate = gate.z - p.z;

        if (p.x >= gate.x) {
          phase = 'recover';
        } else if (phase === 'recover' && p.x < gate.x - 0.30) {
          phase = 'align';
          settleCount = 0;
        }

        if (phase === 'recover') {
          const safeZ = gate.z + (p.z >= gate.z ? 0.52 : -0.52);
          if (Math.abs(p.z - gate.z) < 0.46 && Math.abs(p.y - gate.y) < 0.36) {
            target = { x: p.x + 0.10, y: gate.y, z: safeZ };
          } else {
            target = { x: gate.x - 0.35, y: gate.y, z: safeZ };
          }
        } else if (phase === 'align') {
          const xStage = gate.x - 0.32;
          target = { x: xStage, y: gate.y, z: gate.z };
          kpZ = 12.0; kdZ = 6.0;
          kpY = 10.0; kdY = 5.2;

          let gustSafe = true;
          if (knownParams && obs.t < 11.5) {
            for (let i = 0; i < knownParams.gusts.length; i++) {
              const g = knownParams.gusts[i];
              const gEnd = g.start + g.duration;
              if (obs.t + 0.32 >= g.start && obs.t < g.start + 0.08) gustSafe = false;
              if (obs.t + 0.25 >= gEnd && obs.t < gEnd + 0.06) gustSafe = false;
              if (g.duration <= 0.25 && obs.t >= g.start - 0.25 && obs.t < gEnd + 0.08) gustSafe = false;
            }
          }

          const zOk = Math.abs(dzGate) < 0.016 && Math.abs(v.z) < 0.08;
          const yOk = Math.abs(dyGate) < 0.055 && Math.abs(v.y) < 0.16;
          const xOk = Math.abs(xStage - p.x) < 0.14 && Math.abs(v.x) < 0.25;

          if (zOk && yOk && xOk && gustSafe) settleCount++;
          else settleCount = Math.max(0, settleCount - 1);

          if (settleCount >= 6) {
            phase = 'cross';
          }
        }

        if (phase === 'cross') {
          const tCross = clamp(dxGate / Math.max(v.x, 0.35), 0.02, 0.30);
          const zPred = p.z + v.z * tCross;
          const yPred = p.y + v.y * tCross;

          if (dxGate > 0.075 && (Math.abs(dzGate) > 0.022 || Math.abs(zPred - gate.z) > 0.025 || Math.abs(dyGate) > 0.095 || Math.abs(yPred - gate.y) > 0.11)) {
            phase = 'align';
            settleCount = 0;
            target = { x: Math.min(p.x - 0.04, gate.x - 0.22), y: gate.y, z: gate.z };
            vxRef = 0;
          } else {
            target = { x: gate.x + 0.38, y: gate.y, z: gate.z };
            vxRef = 0.85;
            kpX = 7.5; kdX = 4.2;
            kpZ = 14.0; kdZ = 6.5;
            kpY = 11.0; kdY = 5.5;
          }
        }
      } else {
        const pad = obs.pad.centre;
        if (targetIndex !== 3) {
          targetIndex = 3;
          phase = 'pad_approach';
          settleCount = 0;
          touchCount = 0;
          posIntX = 0; posIntY = 0; posIntZ = 0;
        }

        const distH = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedH = Math.hypot(v.x, v.z);

        if (phase === 'pad_approach') {
          const hoverY = distH > 0.35 ? 0.55 : 0.26;
          target = { x: pad.x, y: hoverY, z: pad.z };
          kpX = 7.5; kdX = 4.8;
          kpZ = 7.5; kdZ = 4.8;
          kpY = 9.0; kdY = 5.2;
          if (distH < 0.09 && speedH < 0.22 && p.y < 0.35) {
            phase = 'pad_descend';
          }
        }

        if (phase === 'pad_descend') {
          target = { x: pad.x, y: 0.06, z: pad.z };
          vyRef = p.y > 0.14 ? -0.32 : -0.15;
          kpX = 8.5; kdX = 5.2;
          kpZ = 8.5; kdZ = 5.2;
          kpY = 8.0; kdY = 5.5;
          if (p.y < 0.16) maxTilt = 0.28;
          if (distH > 0.135 && p.y > 0.10) {
            phase = 'pad_approach';
          }
          if (p.y <= 0.082 && distH <= 0.12 && Math.hypot(v.x, v.y, v.z) < 0.42) {
            phase = 'pad_hold';
          }
        }

        if (phase === 'pad_hold') {
          if (distH > 0.14) {
            phase = 'pad_approach';
          } else {
            touchCount++;
            const holdRoll = clamp(-(Math.sin(att.yaw) * (pad.x - p.x) + Math.cos(att.yaw) * (pad.z - p.z)) * 0.4, -0.08, 0.08);
            const holdPitch = clamp((Math.cos(att.yaw) * (pad.x - p.x) - Math.sin(att.yaw) * (pad.z - p.z)) * 0.4, -0.08, 0.08);
            lastDesiredRoll = holdRoll;
            lastDesiredPitch = holdPitch;
            lastAction = {
              thrust: 0.12,
              roll: holdRoll,
              pitch: holdPitch,
              yawRate: clamp(-5.0 * att.yaw - 0.4 * rates.yaw, -2, 2),
            };
            return lastAction;
          }
        }
      }

      const ex = target.x - p.x;
      const ey = target.y - p.y;
      const ez = target.z - p.z;

      if (Math.hypot(ex, ez) < 0.25) {
        posIntX = clamp(posIntX + ex * dt, -0.25, 0.25);
        posIntZ = clamp(posIntZ + ez * dt, -0.25, 0.25);
      } else {
        posIntX *= 0.95;
        posIntZ *= 0.95;
      }
      if (Math.abs(ey) < 0.30) {
        posIntY = clamp(posIntY + ey * dt, -0.35, 0.35);
      }

      const posEx = clamp(ex, -0.65, 0.65);
      const posEz = clamp(ez, -0.65, 0.65);
      const posEy = clamp(ey, -0.60, 0.60);

      const axFb = kpX * posEx + kdX * (vxRef - v.x) + 1.5 * posIntX;
      const azFb = kpZ * posEz + kdZ * (vzRef - v.z) + 2.2 * posIntZ;
      const ayFb = kpY * posEy + kdY * (vyRef - v.y) + 2.5 * posIntY;

      const axCmd = clamp(axFb - windAccX + (DRAG / massEst) * v.x, -7.5, 7.5);
      const azCmd = clamp(azFb - windAccZ + (DRAG / massEst) * v.z, -7.5, 7.5);
      const ayCmd = clamp(ayFb - dHatY + (DRAG / massEst) * v.y, -4.5, 5.5);

      const totalUp = Math.max(4.0, G + ayCmd);
      const cy = Math.cos(att.yaw);
      const sy = Math.sin(att.yaw);
      const aBodyX = cy * axCmd - sy * azCmd;
      const aBodyZ = sy * axCmd + cy * azCmd;

      const desiredPitch = clamp(Math.atan2(aBodyX, totalUp), -maxTilt, maxTilt);
      const desiredRoll = clamp(Math.atan2(-aBodyZ, Math.hypot(aBodyX, totalUp)), -maxTilt, maxTilt);

      lastDesiredRoll = desiredRoll;
      lastDesiredPitch = desiredPitch;

      const cmdRoll = clamp(
        desiredRoll + 0.32 * (desiredRoll - att.roll) - 0.035 * rates.roll + 1.6 * attIntRoll,
        -maxTilt,
        maxTilt
      );
      const cmdPitch = clamp(
        desiredPitch + 0.32 * (desiredPitch - att.pitch) - 0.035 * rates.pitch + 1.6 * attIntPitch,
        -maxTilt,
        maxTilt
      );

      const tiltFactor = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const sNeededVert = totalUp / tiltFactor;
      const sNeededHoriz = Math.hypot(axCmd, azCmd) / Math.max(0.35, Math.hypot(dirX, dirZ));
      const sTarget = Math.abs(ey) < 0.08 && Math.hypot(axCmd, azCmd) > 5.2
        ? Math.max(sNeededVert, Math.min(sNeededVert + 2.5, sNeededHoriz))
        : sNeededVert;

      const thrust = clamp(sTarget / kThrust, 0.05, 1.0);
      const yawRate = clamp(-6.0 * att.yaw - 8.0 * yawInt - 0.4 * rates.yaw, -2, 2);

      lastAction = { thrust, roll: cmdRoll, pitch: cmdPitch, yawRate };
      return lastAction;
    },
  };
}

