  let dHatX = 0;
  let dHatY = 0;
  let dHatZ = 0;
  let yawInt = 0;
  let attBiasRoll = 0;
  let attBiasPitch = 0;
  let posIntX = 0;
  let posIntY = 0;
  let posIntZ = 0;

  let targetIndex = -1;
  let phase = 'approach';

  function windAt(params, t) {
    let wx = params.baseWind.x;
    let wz = params.baseWind.z;
