      if (Math.abs(ez) < 0.25) posIntZ = clamp(posIntZ + ez * dt, -0.25, 0.25);
      else posIntZ *= 0.95;
      if (Math.abs(ey) < 0.25) posIntY = clamp(posIntY + ey * dt, -0.30, 0.30);
