      const vyDes = vyRef + clamp(1.85 * ey, -1.25, 1.25);

      const axFb = 4.2 * (vxDes - v.x) + 1.4 * posIntX;
      const azFb = 4.5 * (vzDes - v.z) + 1.8 * posIntZ;
      const ayFb = 4.8 * (vyDes - v.y) + 2.0 * posIntY;

